BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
SET LOCAL timezone='UTC';
SELECT jsonb_build_object('columns',(SELECT jsonb_agg(to_jsonb(x) ORDER BY table_schema,table_name,ordinal_position) FROM (SELECT table_schema,table_name,column_name,ordinal_position,data_type,udt_schema,udt_name,is_nullable,column_default,character_maximum_length FROM information_schema.columns WHERE table_schema='ceroa' OR table_schema='public' AND table_name='ceroa_rag_configuration') x),'constraints',(SELECT jsonb_agg(to_jsonb(x) ORDER BY nspname,relname,conname) FROM (SELECT n.nspname,c.relname,k.conname,pg_get_constraintdef(k.oid) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ceroa') x),'indexes',(SELECT jsonb_agg(to_jsonb(x) ORDER BY schemaname,tablename,indexname) FROM (SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='ceroa') x),'tableSecurity',(SELECT jsonb_agg(to_jsonb(x) ORDER BY nspname,relname) FROM (SELECT n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity,c.relacl::text,pg_get_userbyid(c.relowner) AS owner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND (n.nspname='ceroa' OR n.nspname='public' AND c.relname='ceroa_rag_configuration')) x),'policies',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY schemaname,tablename,policyname),'[]'::jsonb) FROM (SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='ceroa' OR schemaname='public' AND tablename='ceroa_rag_configuration') x),'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid)) ORDER BY p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ceroa'),'sequences',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY schemaname,sequencename),'[]'::jsonb) FROM (SELECT schemaname,sequencename,start_value,min_value,max_value,increment_by,cycle,cache_size,last_value FROM pg_sequences WHERE schemaname='ceroa') x));
ROLLBACK;

